    about_story_title_highlight: 'Hikayemiz',
    about_story_p1: 'LingRoot, teknolojiyi kullanarak dil öğrenme deneyimini kökten değiştirmek amacıyla kurulmuş yenilikçi bir platformdur. Misyonumuz, kullanıcıların İngilizce öğrenmek için günlük hayatlarından ödün vermeden, sevdikleri içeriklerle pratik yapabilmelerini sağlamaktır.',
