    about_mission_desc: 'Sevdiğiniz içerikleri kullanarak, hayat tarzınızı değiştirmeden İngilizcenizi geliştirme imkânı sunmak. Bunu en yeni teknolojileri kullanarak, her seviyeden kullanıcıya uygun, kişiselleştirilmiş ve erişilebilir bir öğrenme deneyimi ile gerçekleştirmek.',
    about_vision_subtitle: 'Vizyonumuz',
    about_vision_desc: 'İngilizce başta olmak üzere yabancı dil öğrenimini tüm dünyada insanlar için günlük yaşamın doğal bir parçası haline getirmek. Teknoloji odaklı yaklaşımımızla, dil bariyerlerini ortadan kaldırarak bireylerin bilgiye ve iletişime engelsiz erişebildiği bir gelecek yaratmayı hedefliyoruz.',
    about_why_title: 'Neden',
    about_why_highlight: 'LingRoot',
    about_problem_title: 'Problem',
    about_problem_desc: 'Yoğun iş veya okul hayatı olan pek çok kişinin, ek dil öğrenme seanslarına zaman ayırmakta zorlanması',
    about_opportunity_title: 'Fırsat',
    about_opportunity_desc: 'Gerçek dünyadan içeriklerle öğrenmenin hem daha eğlenceli hem de daha etkili olduğu bilgisi',
    about_solution_title: 'Çözüm',
    about_solution_desc: 'Dil öğrenme sürecini günlük alışkanlıklarla birleştirerek kalıcı ve motive edici bir deneyim sunmak',
    about_values_title: 'Temel',
    about_values_highlight: 'Değerlerimiz',
    about_transparency_title: 'Şeffaflık',
    about_transparency_desc: 'Kullanıcılarımızla her zaman açık ve dürüst iletişim kuruyoruz. Süreçlerimiz ve verileriniz hakkında tam şeffaflık sağlıyoruz.',
    about_innovation_title: 'Yenilikçilik',
    about_innovation_desc: 'En yeni teknolojileri takip ederek, dil öğrenme deneyimini sürekli geliştiren çözümler sunuyoruz.',
    about_user_focus_title: 'Kullanıcı Odaklılık',
    about_user_focus_desc: 'Her karar ve geliştirmede kullanıcı deneyimini merkeze alıyor, ihtiyaçlarınızı önceleyerek hareket ediyoruz.',
    about_security_title: 'Güvenlik ve',
    about_security_highlight: 'Gizlilik',
    about_security_desc: 'LingRoot, kullanıcı güvenliği ve gizliliğini ön planda tutan profesyonel bir yaklaşıma sahiptir. Platformumuzda yaptığınız tüm işlemler ve paylaştığınız veriler, uluslararası standartlarda korunur. Verilerinizin güvenliği bizim için bir öncelik değil, vazgeçilmez bir gerekliliktir.',
    about_cta_title: "LingRoot – We're Rooting for You!",
    about_cta_desc: "Dil öğrenme yolculuğunuzda size kökünden (Root'tan) destek olmayı sürdüreceğiz. Siz de bu yolculukta bize katılarak İngilizce öğreniminin ne kadar keyifli olabileceğini keşfedin.",
    about_cta_button_start: 'Hemen Başla',
    about_cta_button_learn: 'Nasıl Çalıştığını Öğren',
    // How It Works Page
    how_hero_badge: 'Üç Basit Adım',
    how_hero_title: 'LingRoot',
    how_hero_title_highlight: 'Nasıl Çalışır?',
    how_hero_desc: 'Sevdiğin içerikleri kendi İngilizce seviyende dinlemek için sadece üç adım yeterli. Yapay zeka teknolojimiz, içerikleri analiz eder ve seviyenize uygun hale getirir.',
    how_steps_title: 'LingRoot',
    how_steps_highlight: 'Nasıl Çalışır?',
    how_steps_desc: 'Sevdiğin içerikleri kendi İngilizce seviyende dinlemek için sadece üç adım yeterli. Yapay zeka teknolojimiz, içerikleri analiz eder ve seviyenize uygun hale getirir.',
    how_step1_title: 'İçeriğinizi Seçin',
    how_step1_desc: "YouTube videosu, Spotify podcast'i, bir haber yazısı… Sadece linki yapıştır veya metni yükle. LingRoot, farklı kaynaklardan gelen içerikleri destekleyecek esneklikte tasarlanmıştır.",
    how_step2_title: 'Seviyenizi Belirleyin',
    how_step2_desc: "A1'den C2'ye kadar İngilizce seviyenizi seçin. İçerik, senin anlayabileceğin İngilizceye otomatik olarak çevrilir. Dil işleme modeli, cümle yapılarını ve kelime dağarcığını seçilen seviyeye uyarlar.",
    how_step3_title: 'Dinle ve Öğren',
    how_step3_desc: 'İçerik yapay zeka tarafından seslendirilir, altyazı eklenir ve seviyene özel hale gelir. Artık sevdiğin şeyleri dinleyerek İngilizce öğrenebilirsin. Senkronize altyazılar ve anlık çeviri özellikleriyle dinleme deneyimini kontrol edebilirsin.',
    how_tech_title: 'Teknik',
    how_tech_highlight: 'Detaylar',
    how_tech_desc: "LingRoot'un arka planında çalışan yapay zeka sisteminin nasıl işlediğini daha detaylı inceleyelim.",
    how_process_title: 'İçerik İşleme Süreci',
    how_process_step1_title: 'Metin Analizi',
    how_process_step1_desc: 'Yapay zeka, içeriğin zorluğunu, kullanılan dil yapılarını ve kelime dağarcığını analiz eder.',
    how_process_step2_title: 'Seviye Uyarlama',
    how_process_step2_desc: 'CEFR standartlarına göre cümle yapıları sadeleştirilir, karmaşık kelimeler daha basit alternatiflerle değiştirilir.',
    how_process_step3_title: 'Ses Sentezi',
    how_process_step3_desc: 'Sadeleştirilen metin, doğal telaffuzla seslendirilir ve senkronize altyazılar oluşturulur.',
    how_process_step4_title: 'Optimizasyon',
    how_process_step4_desc: 'İçerik, öğrenme açısından en uygun hız ve tonlamada sunulur.',
    how_example_title: 'Örnek Dönüşüm',
    how_example_original_label: 'Orijinal (C2 Seviyesi):',
    how_example_adapted_label: 'A2 Seviyesine Uyarlanmış:',
    how_changes_title: 'Yapılan Değişiklikler:',
    how_change1: 'Karmaşık kelimeler basitleştirildi',
    how_change2: 'Cümle yapısı sadeleştirildi',
    how_change3: 'A2 seviyesi kelime dağarcığı kullanıldı',
    how_faq_title: 'Sık Sorulan Sorular',
    how_faq_q1: "LingRoot'un diğer dil öğrenme uygulamalarından farkı nedir?",
    how_faq_a1: 'LingRoot, aynı içeriği 6 farklı seviyede (A1-C2) dinlemenize olanak tanıyan tek platformdur. Sevdiğiniz içerikleri kendi seviyenize göre dinleyerek daha hızlı ve etkili öğrenirsiniz.',
    how_faq_q2: 'İçerikler nasıl farklı seviyelere dönüştürülüyor?',
    how_faq_a2: 'Gelişmiş yapay zeka sistemimiz, içerikleri analiz eder ve her seviye için uygun kelime dağarcığı, gramer yapıları ve konuşma hızıyla yeniden oluşturur, böylece öğrenme süreciniz için en uygun formatı sunar.',
    how_faq_q3: 'Hangi tür içerikleri kullanabilirim?',
    how_faq_a3: "YouTube videoları, podcast'ler, kendi metin veya ses dosyalarınız gibi çeşitli içerikleri platforma yükleyebilir ve seviyenize göre dönüştürebilirsiniz.",
    how_faq_q4: 'LingRoot hangi İngilizce seviyelerine uygun?',
    how_faq_a4: "A1'den C2'ye kadar tüm CEFR seviyelerine uygun içerikler sunuyoruz. Başlangıç seviyesindeyseniz de, ileri seviyedeyseniz de size uygun içerikler bulacaksınız.",
    how_cta_button: 'Hemen Ücretsiz Deneyin!',
    // Features Page
    features_hero_badge: 'Platform Özellikleri',
    features_hero_title: 'LingRoot',
