    features_hero_desc: 'Benzersiz özelliklerimizle İngilizce öğrenme deneyiminizi tamamen değiştiriyoruz.',
    features_main_title: 'Platform',
    features_main_highlight: 'Özelliklerimiz',
    features_main_desc: 'Teknoloji destekli öğrenme deneyimi için özel olarak tasarlanmış özellikler',
    feature_personalized_title: 'Kişiselleştirilmiş Öğrenme',
    feature_personalized_desc: 'Her içerik, sizin seviyenize ve ilgi alanlarınıza göre özel olarak uyarlanır. Kendi hızınızda ve tarzınızda öğrenin.',
    feature_listening_title: 'Dinleme Pratiği',
    feature_listening_desc: 'Sevdiğiniz içerikleri seviyenize uygun ses dosyalarına dönüştürün ve senkronize altyazılarla dinleme becerilerinizi geliştirin.',
    feature_vocabulary_title: 'Geniş Kelime Havuzu',

    feature_vocabulary_desc: 'Karşılaştığınız yeni kelimeleri kolayca öğrenin, hafızanızda kalıcı hale getirin ve aktif kelime dağarcığınızı genişletin.',
    feature_realworld_title: 'Gerçek Dünya İçerikleri',
    feature_realworld_desc: "Sıkıcı ders kitapları yerine, sevdiğiniz videoları, podcast'leri ve gerçek hayattan içerikleri kullanarak öğrenin.",
    feature_progress_title: 'İlerleme Takibi',
    feature_progress_desc: 'Gelişiminizi adım adım takip edin, analizlerinizi görüntüleyin ve motivasyonunuzu her zaman yüksek tutun.',
    feature_flexible_title: 'Esnek ve Erişilebilir',
    feature_flexible_desc: 'İstediğiniz zaman, istediğiniz yerden öğrenme özgürlüğünün tadını çıkarın. Günlük programınıza göre esnek öğrenme.',
    features_promo_title: 'En Önemli Özelliğimiz: 6 Seviyeli İçerikler',
    features_promo_desc: "LingRoot'un en benzersiz özelliği, aynı içeriği A1'den C2'ye kadar 6 farklı zorluk seviyesinde sunabilmesidir. Böylece sevdiğiniz bir içeriği önce kendi seviyenizde anlayabilir, sonra daha zor seviyelere geçerek İngilizcenizi geliştirebilirsiniz.",
    features_promo_level_suffix: 'Seviyesi',
    features_promo_button: 'Hemen Deneyin',
    features_tech_title: 'Teknik Özelliklerimiz',
    feature_tech_ai_title: 'Yapay Zeka Destekli İçerik Dönüşümü',
    feature_tech_ai_desc: 'Gelişmiş yapay zeka algoritmamız, metinleri ve videoları otomatik olarak farklı İngilizce seviyelerine uyarlar, kelime dağarcığını ve gramer yapısını kişiselleştirerek öğrenme sürecinizi optimize eder.',
    feature_tech_subtitle_title: 'Otomatik Altyazı Oluşturma',
    feature_tech_subtitle_desc: 'Her video için otomatik olarak doğru ve zaman kodlu altyazılar oluşturur. İstediğiniz seviyede altyazı gösterebilir, kelimelere tıklayarak anlamlarını öğrenebilirsiniz.',
    feature_tech_vocab_title: 'Kelime ve İfade Kaydetme',
    feature_tech_vocab_desc: 'İçeriklerde karşılaştığınız yeni kelime ve ifadeleri kişisel sözlüğünüze kaydedebilir, daha sonra özel oluşturulmuş alıştırmalarla pekiştirebilirsiniz.',
    feature_tech_offline_title: 'Çevrimdışı Erişim',
    feature_tech_offline_desc: 'Favori içeriklerinizi indirerek internet bağlantısı olmadan da erişebilir, öğrenmeye her yerde ve her zaman devam edebilirsiniz.',
