    pricing_popular_badge: 'EN POPÜLER',
    pricing_free_desc: 'Platformu risksiz denemek için tasarlanmış ücretsiz başlangıç paketi.',
    pricing_free_feature1: 'Sınırlı sayıda kısa ses üretimi ile LingRoot deneyimini risksiz keşfedin',
    pricing_free_feature2: 'Tüm CEFR seviyeleri (A1–C1) için örnek içeriklere erişim',
    pricing_free_feature3: 'Standart ses kalitesi (Standard kategori)',
    pricing_free_feature4: 'Metinden hızlı ses oluşturma deneyimi',
    pricing_gold_desc: 'Her gün düzenli İngilizce dinleme ve tekrar yapmak isteyenler için ideal günlük pratik paketi.',
    pricing_gold_feature1: 'Hedef kullanım: günde ortalama ~1 saat İngilizce dinleme ve pratik senaryoları',
    pricing_gold_feature2: 'Gerçek dakikalar; seçilen ses kalitesi ve adil kullanım limitlerine göre sistem tarafından otomatik yönetilir',
    pricing_gold_feature3: 'Standart + Premium (Wavenet / Neural2) ses kalitesi – daha doğal ve akıcı sesler',
    pricing_gold_feature4: 'Metin, konu, kitap ve dokümanlardan ses oluşturma',
    pricing_platinum_desc: 'Yoğun içerik üretenler, öğretmenler ve ileri seviye kullanıcılar için tasarlanmış profesyonel paket.',
    pricing_platinum_feature1: 'Hedef kullanım: günde ~3 saate kadar yoğun pratik ve içerik üretimi',
    pricing_platinum_feature2: 'Gerçek sınırlar; API maliyetine göre adil kullanım politikasıyla sistem tarafından takip edilir',
    pricing_platinum_feature3: 'Tüm ses kategorileri: Standard, Premium (Wavenet / Neural2), Studio ve 3D (Chirp3D)',
    pricing_platinum_feature4: 'Uzun metinler ve çok bölümlü içerikler için yüksek toplam dakika potansiyeli',
    pricing_faq_title: 'Sık Sorulan Sorular',
    pricing_faq_q1: 'Üyelik planları arasında nasıl geçiş yapabilirim?',
    pricing_faq_a1: 'Hesap ayarlarınızdan dilediğiniz zaman planınızı yükseltebilir veya değiştirebilirsiniz. Yıllık plandan aylık plana geçiş yapmak isterseniz, mevcut abonelik sürenizin sonunda değişiklik gerçekleşir.',
    pricing_faq_q2: 'Ödememi nasıl yapabilirim?',
    pricing_faq_a2: 'Kredi kartı, banka kartı veya PayPal ile güvenli ödeme yapabilirsiniz. Tüm ödemeler SSL ile şifrelenir ve bilgileriniz güvende tutulur.',
    pricing_faq_q3: 'İade politikanız nedir?',
    pricing_faq_a3: 'Satın alma işleminizden itibaren 14 gün içerisinde, herhangi bir sebep belirtmeden iade talep edebilirsiniz. İade talepleri için destek ekibimizle iletişime geçmeniz yeterlidir.',
    pricing_faq_q4: 'Ücretsiz plan ile ne kadar ileri gidebilirim?',
    pricing_faq_a4: 'Ücretsiz planımız, platformumuzun temel özelliklerini denemeniz için tasarlanmıştır. Sınırlı sayıda ve sürede kısa sesler üreterek LingRoot deneyimini risksiz keşfedebilirsiniz. Daha uzun ve düzenli günlük kullanım için Gold ve Platin planlarımızı öneririz.',
    pricing_faq_q5: 'Planlarınız sınırsız mı?',
    pricing_faq_a5: 'Hayır. Tüm planlarımızda kullanım, altyapı sağlayıcılarının maliyetlerine göre belirlenen adil kullanım limitleri ile otomatik olarak takip edilir. Hedef profil olarak Gold plan günlük yaklaşık ~1 saat, Platin plan ise günde ~3 saate kadar yoğun kullanım senaryolarına göre tasarlanmıştır.',
    pricing_cta_title: 'Hala kararsız mısınız?',
    pricing_cta_desc: "Risk almadan ücretsiz planımızla başlayın ve LingRoot'un İngilizce öğrenme deneyiminizi nasıl tamamen değiştireceğini keşfedin.",
    pricing_cta_button: 'Ücretsiz Hesap Oluştur',
