    privacy_international_transfers_text:
      "Hizmet sağlayıcılarımızın bazıları Türkiye/AEA dışında bulunabilir. Bu durumda kişisel verileriniz yurt dışına aktarılabilir. Uygulanabilir mevzuata göre gerekli güvenlik önlemlerini ve uygun koruma mekanizmalarını uygulamayı hedefleriz.",
    privacy_retention_title: "Saklama Süreleri",
