    // About Page
    about_hero_badge: 'About LingRoot',
    about_hero_title: 'Our Story',
    about_hero_description: 'An innovative platform established to radically change the language learning experience with technology.',
    about_hero_quote: '"You don\'t need to change your life to learn English – just keep listening"',
    about_story_title: 'Our',
    about_story_title_highlight: 'Story',
    about_story_p1: "LingRoot is an innovative platform established with the aim of radically changing the language learning experience using technology. Our mission is to enable users to practice with content they love, without compromising their daily lives to learn English.",
    about_story_p2: "In this direction, LingRoot takes content you already follow with interest, such as YouTube videos, podcasts, and blog posts, and adapts them to your chosen English level. While doing this, it uses AI-supported natural language processing technologies to simplify content, voice it with text-to-speech, and add subtitles to facilitate your learning.",
    about_story_p3: "As the LingRoot team, we believe that thanks to the opportunities offered by the digital age, language learning can cease to be a lesson or obligation and be integrated into life. We work constantly to add value to our users, transforming real-world content into a personalized learning experience.",
    about_story_milestone_text: "We set out based in Istanbul and have been constantly improving our platform with feedback from our users ever since.",
    about_mission_title: 'Mission &',
    about_mission_highlight: 'Vision',
    about_mission_subtitle: 'Our Mission',
    about_mission_desc: 'To offer the opportunity to improve your English using content you love, without changing your lifestyle. To achieve this using the latest technologies with a personalized and accessible learning experience suitable for users of all levels.',
    about_vision_subtitle: 'Our Vision',
    about_vision_desc: 'To make foreign language learning, especially English, a natural part of daily life for people all over the world. With our technology-focused approach, we aim to create a future where language barriers are eliminated and individuals can access information and communication without obstacles.',
    about_why_title: 'Why',
    about_why_highlight: 'LingRoot',
    about_problem_title: 'Problem',
