    // How It Works Page
    how_hero_badge: 'Three Simple Steps',
    how_hero_title: 'How',
    how_hero_title_highlight: 'LingRoot Works?',
    how_hero_desc: 'Just three steps are enough to listen to content you love at your own English level. Our AI technology analyzes content and adapts it to your level.',
    how_steps_title: 'How',
    how_steps_highlight: 'LingRoot Works?',
    how_steps_desc: 'Just three steps are enough to listen to content you love at your own English level. Our AI technology analyzes content and adapts it to your level.',
    how_step1_title: 'Choose Your Content',
    how_step1_desc: "A YouTube video, a Spotify podcast, a news article... Just paste the link or upload the text. LingRoot is designed with the flexibility to support content from different sources.",
    how_step2_title: 'Set Your Level',
    how_step2_desc: "Select your English level from A1 to C2. The content is automatically translated into English you can understand. The natural language processing model adapts sentence structures and vocabulary to the selected level.",
    how_step3_title: 'Listen and Learn',
    how_step3_desc: 'The content is voiced by AI, subtitles are added, and it becomes specific to your level. Now you can learn English by listening to things you love. You can control the listening experience with synchronized subtitles and instant translation features.',
    how_tech_title: 'Technical',
    how_tech_highlight: 'Details',
    how_tech_desc: "Let's examine in more detail how the AI system running in the background of LingRoot works.",
    how_process_title: 'Content Processing',
    how_process_step1_title: 'Text Analysis',
    how_process_step1_desc: 'AI analyzes the difficulty of the content, language structures used, and vocabulary.',
    how_process_step2_title: 'Level Adaptation',
    how_process_step2_desc: 'Sentence structures are simplified according to CEFR standards, complex words are replaced with simpler alternatives.',
    how_process_step3_title: 'Voice Synthesis',
    how_process_step3_desc: 'The simplified text is voiced with natural pronunciation and synchronized subtitles are created.',
    how_process_step4_title: 'Optimization',
    how_process_step4_desc: 'Content is presented at the most appropriate speed and intonation for learning.',
    how_example_title: 'Example Conversion',
    how_example_original_label: 'Original (C2 Level):',
    how_example_adapted_label: 'Adapted to A2 Level:',
