    how_change1: 'Complex words simplified',
    how_change2: 'Sentence structure simplified',
    how_change3: 'A2 level vocabulary used',
    how_faq_title: 'Frequently Asked Questions',
    how_faq_q1: "What is the difference between LingRoot and other language learning apps?",
    how_faq_a1: 'LingRoot is the only platform that allows you to listen to the same content at 6 different levels (A1-C2). You learn faster and more effectively by listening to content you love at your own level.',
    how_faq_q2: 'How is content converted to different levels?',
    how_faq_a2: 'Our advanced AI system analyzes content and recreates it with vocabulary, grammar structures, and speaking speed appropriate for each level, offering the most suitable format for your learning process.',
    how_faq_q3: 'What types of content can I use?',
    how_faq_a3: "You can upload various content such as YouTube videos, podcasts, your own text or audio files to the platform and convert them according to your level.",
    how_faq_q4: 'Which English levels is LingRoot suitable for?',
    how_faq_a4: "We offer content suitable for all CEFR levels from A1 to C2. Whether you are at beginner or advanced level, you will find content suitable for you.",
